import{c as a,Q as n,j as p,m as s}from"./chunks/framework.DOi4mjdC.js";const e="data:image/png;base64,",i="/assets/%E5%8D%B7%E7%A7%AF%E5%8F%8D%E5%90%91%E6%9D%83%E9%87%8D%E4%BC%A0%E6%92%AD%E7%A4%BA%E6%84%8F%E5%9B%BE.CUbR0W3t.png",o="/assets/%E5%8D%B7%E7%A7%AF%E5%8F%8D%E5%90%91%E6%9D%83%E9%87%8D%E8%AE%A1%E7%AE%97%E8%BF%87%E7%A8%8B%E7%A4%BA%E6%84%8F%E5%9B%BE.CcU1fBjc.png",C=JSON.parse('{"title":"Conv3DBackpropFilter使用说明","description":"","frontmatter":{},"headers":[{"level":1,"title":"Conv3DBackpropFilter使用说明","slug":"conv3dbackpropfilter使用说明"},{"level":2,"title":"需要包含的头文件","slug":"需要包含的头文件"}],"relativePath":"api/SIMD-API/高阶API/卷积计算/Conv3DBackpropFilter/Conv3DBackpropFilter-Kernel侧接口/Conv3DBackpropFilter使用说明.md","filePath":"api/SIMD-API/高阶API/卷积计算/Conv3DBackpropFilter/Conv3DBackpropFilter-Kernel侧接口/Conv3DBackpropFilter使用说明.md"}'),l={name:"api/SIMD-API/高阶API/卷积计算/Conv3DBackpropFilter/Conv3DBackpropFilter-Kernel侧接口/Conv3DBackpropFilter使用说明.md"};function r(c,t,d,g,u,h){return n(),p("div",null,[...t[0]||(t[0]=[s('<h1 id="conv3dbackpropfilter使用说明" tabindex="-1">Conv3DBackpropFilter使用说明 <a class="header-anchor" href="#conv3dbackpropfilter使用说明" aria-label="Permalink to &quot;Conv3DBackpropFilter使用说明&quot;">​</a></h1><p>Ascend C提供一组Conv3DBackpropFilter高阶API，便于用户快速实现卷积的反向运算，求解反向传播的误差。</p><p>卷积反向的权重传播如<a href="#fig1710410547569">图1</a>，卷积反向权重计算如<a href="#fig25291917533">图2</a>。</p><p>Conv3dBackpropFilter的计算公式为：</p><p><img src="'+e+'" alt=""></p><ul><li>X为卷积的特征矩阵Input。</li><li>∂L/∂Y为卷积正向损失函数对输出Y的梯度GradOutput，作为求反向传播误差∂L/∂W的输入，即卷积的输出反向GradOutput。</li><li>∂L/∂W为Weight权重的反向传播误差GradWeight。</li></ul><p><strong>图 1</strong> 卷积反向权重传播示意图<br><img src="'+i+'" alt="" title="卷积反向权重传播示意图"></p><p><strong>图 2</strong> 卷积反向权重计算过程示意图<br><img src="'+o+`" alt="" title="卷积反向权重计算过程示意图"></p><p>Kernel侧实现Conv3DBackpropFilter求解反向传播误差运算的步骤概括为：</p><ol><li>创建Conv3DBackpropFilter对象。</li><li>初始化操作。</li><li>设置卷积的特征矩阵Input、卷积的输出反向GradOutput。</li><li>完成卷积反向操作。</li><li>结束卷积反向操作。</li></ol><p>使用Conv3DBackpropFilter高阶API求解反向传播误差运算的具体步骤如下：</p><ol><li><p>创建Conv3DBackpropFilter对象。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;lib/conv_backprop/conv3d_bp_filter_api.h&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>using inputType = ConvBackpropApi::ConvType &lt;ConvCommonApi::TPosition::GM, ConvCommonApi::ConvFormat::NDC1HWC0, inputType&gt;;</span></span>
<span class="line"><span>using weightSizeType = ConvBackpropApi::ConvType&lt;ConvCommonApi::TPosition::GM, ConvCommonApi::ConvFormat::ND, int32_t&gt;;</span></span>
<span class="line"><span>using gradOutputType = ConvBackpropApi::ConvType&lt;ConvCommonApi::TPosition::GM, ConvCommonApi::ConvFormat::NDC1HWC0, gradOutputType&gt;;</span></span>
<span class="line"><span>using gradWeightType = ConvBackpropApi::ConvType &lt;ConvCommonApi::TPosition::GM, ConvCommonApi::ConvFormat::FRACTAL_Z_3D, gradWeightType&gt;;</span></span>
<span class="line"><span>ConvBackpropApi::Conv3DBackpropFilter &lt;inputType, weightSizeType, gradOutputType, gradWeightType&gt; gradWeight_;</span></span></code></pre></div><p>创建对象时需要传入特征矩阵Input、权重矩阵Weight的shape信息WeightSize、GradOutput和GradWeight的参数类型信息，类型信息通过<a href="#table19081115275">ConvType</a>来定义，包括：内存逻辑位置、数据格式、数据类型。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;TPosition POSITION, ConvFormat FORMAT, typename T&gt;</span></span>
<span class="line"><span>struct ConvType {</span></span>
<span class="line"><span>    constexpr static TPosition pos = POSITION;    // Convolution输入或输出的逻辑位置</span></span>
<span class="line"><span>    constexpr static ConvFormat format = FORMAT;  // Convolution输入或输出的数据格式</span></span>
<span class="line"><span>    using Type = T;                               // Convolution输入或输出的数据类型</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>下面简要介绍在创建对象时使用到的相关数据结构，开发者可选择性地了解这些内容。用于创建Conv3DBackpropFilter对象的数据结构定义如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>using Conv3DBackpropFilter = Conv3DBpFilterIntf&lt;Conv3DBpFilterCfg&lt;INPUT_TYPE, WEIGHT_TYPE, GRAD_OUTPUT_TYPE, GRAD_WEIGHT_TYPE&gt;, Conv3DBpFilterImpl&gt;;</span></span></code></pre></div><p>其中，Conv3DBpFilterIntf、Conv3DBpFilterCfg数据结构定义如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;class Config_, template &lt;typename, class&gt; class Impl&gt;</span></span>
<span class="line"><span>struct Conv3DBpFilterIntf {</span></span>
<span class="line"><span>}</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;class A, class B, class C, class D&gt;</span></span>
<span class="line"><span>struct Conv3DBpFilterCfg : public ConvBpContext&lt;A, B, C, D&gt;{</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><strong>表 1</strong> ConvType说明</p></li></ol><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td>POSITION</td><td>内存逻辑位置。 Input X矩阵可设置为TPosition::GMWeightSize可设置为TPosition::GMGradOutput矩阵可设置为TPosition::GMGradWeight矩阵可设置为TPosition::GM</td></tr><tr><td>ConvFormat</td><td>数据格式。 Input矩阵可设置为ConvFormat::NDC1HWC0WeightSize矩阵可设置为ConvFormat::NDGradOutput矩阵可设置为ConvFormat::NDC1HWC0GradWeight矩阵可设置为ConvFormat::FRACTAL_Z_3D</td></tr><tr><td>TYPE</td><td>数据类型。Input矩阵可设置为half、bfloat16_tWeightSize可设置为int32_tGradOutput矩阵可设置为half、bfloat16_tGradWeight矩阵可设置为float 注意：Input、GradOutput数据类型需要一致，具体数据类型组合关系请参考表2。</td></tr></tbody></table><pre><code>**表 2**  Conv3DBackpropFilter输入输出数据类型的组合说明
</code></pre><table tabindex="0"><thead><tr><th>Input</th><th>WeightSize</th><th>GradOutput</th><th>GradWeight</th><th>支持平台</th></tr></thead><tbody><tr><td>half</td><td>int32_t</td><td>half</td><td>float</td><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品Atlas A2 训练系列产品/Atlas A2 推理系列产品</td></tr><tr><td>bfloat16_t</td><td>int32_t</td><td>bfloat16_t</td><td>float</td><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品Atlas A2 训练系列产品/Atlas A2 推理系列产品</td></tr></tbody></table><ol start="2"><li><p>初始化操作。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gradWeight_.Init(&amp;(tilingData-&gt;dwTiling)); // 初始化gradWeight_相关参数</span></span></code></pre></div></li><li><p>设置卷积的特征矩阵Input、卷积的输出反向GradOutput。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gradWeight_.SetGradOutput(gradOutputGm_[offsetA_]);    // 设置矩阵gradOutput</span></span>
<span class="line"><span>gradWeight_.SetInput(inputGm_[offsetB_]);    // 设置矩阵Input</span></span>
<span class="line"><span>gradWeight_.SetSingleShape(singleShapeM, singleShapeN, singleShapeK); // 设置需要计算的形状</span></span>
<span class="line"><span>gradWeight_.SetStartPosition(hoStartIdx_); // 设置初始位置</span></span></code></pre></div></li><li><p>完成卷积反向操作。</p><p>调用<a href="./Iterate-125.html">Iterate</a>完成单次迭代计算，叠加while循环完成单核全量数据的计算。Iterate方式，可以自行控制迭代次数，完成所需数据量的计算。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>while (gradWeight_.Iterate()) {   </span></span>
<span class="line"><span>    gradWeight_.GetTensorC(gradWeightGm_[offsetC_]); </span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p>结束卷积反向操作。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gradWeight_.End();</span></span></code></pre></div></li></ol><h2 id="需要包含的头文件" tabindex="-1">需要包含的头文件 <a class="header-anchor" href="#需要包含的头文件" aria-label="Permalink to &quot;需要包含的头文件&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;lib/conv_backprop/conv3d_bp_filter_api.h&quot;</span></span></code></pre></div>`,18)])])}const A=a(l,[["render",r]]);export{C as __pageData,A as default};
